'use client';

import * as React from 'react';

// @interlace/picture-reveal v1.1.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/picture-reveal
// What changed since: https://ds.interlace.tools/c/picture-reveal#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — PictureReveal
 *
 * A picture under tiles that come away a few at a time while the room
 * guesses. The presenter moves `step`; every screen uncovers the same tiles
 * in the same seeded order, spread across the picture. Phones guess with
 * `TypeAnswer` (or `QuizQuestion`), and `guessPoints` pays an early right
 * guess more.
 *
 * A picture cannot be guessed by someone who cannot see it, so the round
 * carries `clues`: one line of text per step, shown and announced as the
 * tiles come off, so a screen reader user plays the same round. The image
 * has no text alternative until the reveal, when it gets `alt` and the
 * answer is said.
 *
 * ## Anatomy
 *
 *   PictureReveal                  (figure — data-slot="picture-reveal", data-state=hidden|revealing|revealed)
 *     ├─ div                       (data-slot="picture-reveal-frame": the picture and its tiles)
 *     │   ├─ img                   (alt only once revealed)
 *     │   └─ div aria-hidden       (data-slot="picture-reveal-tiles": span × cols·rows, data-off)
 *     ├─ ol                        (data-slot="picture-reveal-clues": the clues so far)
 *     ├─ span sr-only aria-live    (data-slot="picture-reveal-status": "6 of 16 tiles off. Clue: …")
 *     └─ figcaption                (data-slot="picture-reveal-answer": on the reveal)
 *
 * ## Motion
 *
 * Tiles that come off together fade and shrink away (`--duration-base`), staggered over
 * 150ms in all, so the eye sees where the picture opened. On the reveal the
 * rest go at once. Under reduced motion they are simply gone.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                  |
 * | ---- | ------------------------- | --------------------------------------------------- |
 * | R4   | Extends native el         | `figure` props                                      |
 * | R6   | data-slot per part        | picture-reveal / -frame / -tiles / -clues / -status / -answer |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                   |
 * | R8   | Enums, not booleans       | `size`                                              |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                |
 * | R26  | A11y                      | clues in step with the tiles; no alt until the reveal; status announced |
 */

import { cn } from '@/lib/utils';
import { revealOrder, tilesAt } from '@/components/ui/games/picture-reveal-model';

export const MIN_VIEWPORT = 320 as const;

interface PictureRevealLabels {
  /** Announced as tiles come off. @default (off, total) => `${off} of ${total} tiles off.` */
  status?: (off: number, total: number) => string;
  /** Before a clue in the announcement. @default 'Clue:' */
  clue?: string;
  /** Names the clue list. @default 'Clues' */
  clues?: string;
  /** Announced on the reveal, before the answer. @default 'The answer:' */
  answer?: string;
}

type PictureRevealProps = Omit<React.ComponentProps<'figure'>, 'children'> & {
  src: string;
  /** The picture in words, given to the image only on the reveal. */
  alt: string;
  /** The answer, shown under the picture on the reveal. @default alt */
  answer?: React.ReactNode;
  /** How far along the round is, 0 to `steps`. */
  step: number;
  /** @default 8 */
  steps?: number;
  /** Show everything: the picture, its alt, the answer. */
  revealed?: boolean;
  /** @default 4 */
  cols?: number;
  /** @default 3 */
  rows?: number;
  /** Seeds the order the tiles come off. Use the round's id. */
  seed: number | string;
  /** One line of text per step, for everyone, and the only way to play without sight. */
  clues?: readonly string[];
  /** `stage` for a shared screen. @default 'default' */
  size?: 'default' | 'stage';
  labels?: PictureRevealLabels;
};

function PictureReveal({
  src,
  alt,
  answer,
  step,
  steps = 8,
  revealed = false,
  cols = 4,
  rows = 3,
  seed,
  clues = [],
  size = 'default',
  labels,
  className,
  ...props
}: PictureRevealProps) {
  const c = Math.max(1, Math.floor(cols));
  const r = Math.max(1, Math.floor(rows));
  const total = c * r;
  const order = React.useMemo(() => revealOrder(total, seed), [total, seed]);
  const off = revealed ? total : tilesAt(step, steps, total);
  const rank = React.useMemo(() => {
    const m: number[] = Array.from({ length: total }, () => 0);
    order.forEach((tile, i) => {
      m[tile] = i;
    });
    return m;
  }, [order, total]);
  const shownClues = revealed ? clues : clues.slice(0, Math.min(clues.length, Math.max(0, Math.floor(step))));
  const prevOff = React.useRef(off);
  const before = prevOff.current;
  React.useEffect(() => {
    prevOff.current = off;
  }, [off]);
  const stage = size === 'stage';
  const lastClue = shownClues.at(-1);
  const status = revealed
    ? `${labels?.answer ?? 'The answer:'} ${alt}`
    : off === 0 && shownClues.length === 0
      ? ''
      : `${(labels?.status ?? ((o: number, t: number) => `${o} of ${t} tiles off.`))(off, total)}${lastClue ? ` ${labels?.clue ?? 'Clue:'} ${lastClue}` : ''}`;

  return (
    <figure
      data-slot="picture-reveal"
      data-state={revealed ? 'revealed' : off === 0 ? 'hidden' : 'revealing'}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('grid gap-3', className)}
      {...props}
    >
      <div
        data-slot="picture-reveal-frame"
        className="bg-muted relative w-full overflow-hidden rounded-xl border"
        style={{ aspectRatio: `${c} / ${r}` }}
      >
        <img
          src={src}
          alt={revealed ? alt : ''}
          aria-hidden={revealed ? undefined : true}
          draggable={false}
          className="absolute inset-0 size-full object-cover select-none"
        />
        <div
          aria-hidden
          data-slot="picture-reveal-tiles"
          className="absolute inset-0 grid"
          style={{ gridTemplateColumns: `repeat(${c}, 1fr)`, gridTemplateRows: `repeat(${r}, 1fr)` }}
        >
          {Array.from({ length: total }, (_, tile) => {
            const k = rank[tile] as number;
            const gone = k < off;
            // Tiles leaving in this step share a 150ms stagger, in their reveal order.
            const leaving = gone && k >= before ? k - before : 0;
            const batch = Math.max(1, off - before);
            return (
              <span
                // Tiles are fixed places on the picture: the index is their identity.
                key={`tile-${tile}`}
                data-off={gone ? '' : undefined}
                className={cn(
                  'bg-card text-muted-foreground border-background grid place-items-center border-2 font-semibold',
                  stage ? 'text-3xl' : 'text-xl',
                  'motion-safe:transition-[opacity,transform] motion-safe:duration-(--duration-base) motion-safe:ease-exit',
                  gone && 'scale-90 opacity-0',
                )}
                style={
                  gone && !revealed && batch > 1
                    ? { transitionDelay: `${Math.round((leaving / batch) * 150)}ms` }
                    : undefined
                }
              >
                ?
              </span>
            );
          })}
        </div>
      </div>
      {clues.length > 0 ? (
        <ol
          data-slot="picture-reveal-clues"
          aria-label={labels?.clues ?? 'Clues'}
          className={cn('grid gap-1 empty:hidden', stage ? 'text-lg' : 'text-sm')}
        >
          {shownClues.map((clue, i) => (
            <li
              // Clues come in a fixed order; the position is their identity.
              key={`clue-${i}`}
              className="text-muted-foreground flex gap-2"
            >
              <span aria-hidden className="text-foreground font-semibold tabular-nums">
                {i + 1}.
              </span>
              <span>{clue}</span>
            </li>
          ))}
        </ol>
      ) : null}
      <span data-slot="picture-reveal-status" aria-live="polite" className="sr-only">
        {status}
      </span>
      {revealed ? (
        <figcaption
          data-slot="picture-reveal-answer"
          className={cn('font-heading font-semibold text-balance', stage ? 'text-section' : 'text-xl')}
        >
          {answer ?? alt}
        </figcaption>
      ) : null}
    </figure>
  );
}
PictureReveal.displayName = 'PictureReveal';

export { PictureReveal };
export type { PictureRevealProps, PictureRevealLabels };

export type DayKey = string;

const DAY_MS = 86_400_000;
const KEY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * The calendar day `date` falls on in `timeZone` (an IANA name such as
 * `"Europe/Paris"`). Without a time zone, the runtime's own is used, which on
 * a server is usually UTC: pass the player's zone when the page renders on
 * one.
 */
export function dayKey(date: Date | number = Date.now(), timeZone?: string): DayKey {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(typeof date === 'number' ? new Date(date) : date);
  const part = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${part.year}-${part.month}-${part.day}`;
}

/** True when `value` is a well-formed day key for a real date. */
export function isDayKey(value: unknown): value is DayKey {
  if (typeof value !== 'string') return false;
  const m = KEY_RE.exec(value);
  if (!m) return false;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3];
}

function toUtc(key: DayKey): number {
  const m = KEY_RE.exec(key);
  if (!m) throw new RangeError(`Not a day key: "${key}" (expected YYYY-MM-DD)`);
  return Date.UTC(+m[1], +m[2] - 1, +m[3]);
}

/** Midnight UTC of the day, as a Date: the safe way to format a key with Intl. */
export function dayKeyToDate(key: DayKey): Date {
  return new Date(toUtc(key));
}

/** The key `days` after `key` (negative goes back). */
export function addDays(key: DayKey, days: number): DayKey {
  return new Date(toUtc(key) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Whole days from `from` to `to`; negative when `to` is earlier. */
export function daysBetween(from: DayKey, to: DayKey): number {
  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
}

/** Day of the week, 0 for Sunday to 6 for Saturday, as `Date.getDay` counts. */
export function weekdayOf(key: DayKey): number {
  return new Date(toUtc(key)).getUTCDay();
}

/**
 * The puzzle's number: 1 on `firstDay`, 2 the day after. Before `firstDay`
 * it is 0 or less, which a caller should treat as "not started".
 */
export function puzzleNumber(key: DayKey, firstDay: DayKey): number {
  return daysBetween(firstDay, key) + 1;
}

/** FNV-1a, 32-bit: a small, stable string hash for seeds. */
export function hashString(value: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/**
 * A seeded generator of numbers in [0, 1) (mulberry32). Good enough to deal
 * puzzles and shuffle answers the same way everywhere; not for anything
 * secret.
 */
export function seededRandom(seed: number | string): () => number {
  let a = typeof seed === 'string' ? hashString(seed) : seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296;
  };
}

/** A copy of `items` in a seeded order (Fisher–Yates). */
export function seededShuffle<T>(items: readonly T[], seed: number | string): T[] {
  const out = items.slice();
  const random = seededRandom(seed);
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j] as T, out[i] as T];
  }
  return out;
}

export interface DailyIndexOptions {
  /** The day puzzle 1 ran. */
  firstDay: DayKey;
  /** `sequence` walks the pool in order; `shuffle` deals it in a seeded order per cycle. @default 'sequence' */
  order?: 'sequence' | 'shuffle';
  /** Changes the shuffled order. @default 'daily' */
  seed?: string;
}

/**
 * Which item of a pool of `size` the day gets, or -1 for an empty pool or a
 * day before `firstDay`.
 */
export function dailyIndex(key: DayKey, size: number, options: DailyIndexOptions): number {
  const n = puzzleNumber(key, options.firstDay);
  if (size <= 0 || n < 1) return -1;
  const position = (n - 1) % size;
  if ((options.order ?? 'sequence') === 'sequence') return position;
  const cycle = Math.floor((n - 1) / size);
  const order = seededShuffle(
    Array.from({ length: size }, (_, i) => i),
    `${options.seed ?? 'daily'}:${cycle}`,
  );
  return order[position] as number;
}

/** The day's item from `pool`, or undefined when there is none. */
export function dailyItem<T>(pool: readonly T[], key: DayKey, options: DailyIndexOptions): T | undefined {
  const i = dailyIndex(key, pool.length, options);
  return i < 0 ? undefined : pool[i];
}

/**
 * Milliseconds until the next day starts in `timeZone`. On a day that a
 * clock change makes 23 or 25 hours long the answer can be off by that hour,
 * which is fine for a countdown and is why it is not used to pick puzzles.
 */
export function msUntilNextDay(now: Date | number = Date.now(), timeZone?: string): number {
  const date = typeof now === 'number' ? new Date(now) : now;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);
  const part = Object.fromEntries(parts.map((p) => [p.type, Number(p.value)]));
  const elapsed =
    ((part.hour! * 60 + part.minute!) * 60 + part.second!) * 1000 + date.getMilliseconds();
  return DAY_MS - elapsed;
}

/**
 * @interlace/ui — games/daily
 *
 * The calendar under a daily game: which day it is for a player, which
 * puzzle that day gets, its number, and how long until the next one. Pure
 * functions, no React, no storage. Every component in `games/` builds on
 * these, and a server can call them too, so the puzzle a page renders and
 * the one a score is checked against come from the same arithmetic.
 *
 * ## Day keys
 *
 * A day is an ISO date string, `"2026-11-24"`, read in a time zone. Keys
 * sort as strings, survive JSON and storage unchanged, and compare without
 * a Date. Arithmetic on them runs in UTC, where every day has 24 hours, so
 * daylight-saving changes never skip or repeat a day.
 *
 * ## The puzzle of the day
 *
 * `dailyIndex` maps a day to an item in a pool. `order: 'sequence'` walks
 * the pool in order and starts again at the end. `order: 'shuffle'` deals
 * the pool in a seeded order that changes every cycle, and never repeats an
 * item inside a cycle. Both are deterministic: the same day, pool size and
 * seed give the same item on every device.
 */

/** An ISO calendar date, `YYYY-MM-DD`. */

import { seededShuffle } from '@/components/ui/games/daily';

/**
 * @interlace/ui — picture-reveal-model
 *
 * A picture hidden under tiles that come away a few at a time while the
 * room guesses. The order is seeded, so every screen (and a recap) uncovers
 * the same tiles in the same order, and it is spread out: a few tiles from
 * all over the picture say more, sooner, than a corner.
 *
 * `revealOrder` gives the tiles' order. `tilesAt` says how many are off
 * after a step, spread evenly so the last step shows the whole picture.
 * `guessPoints` pays an earlier right guess more: full points before any
 * tile is off, down to `floor` of them at the last step.
 */

/** Every tile index, in the order the tiles come off. */
export function revealOrder(tiles: number, seed: number | string): number[] {
  const n = Math.max(0, Math.floor(tiles));
  return seededShuffle(
    Array.from({ length: n }, (_, i) => i),
    seed,
  );
}

/** Tiles off after `step` of `steps` (0 shows none; `steps` shows all). */
export function tilesAt(step: number, steps: number, tiles: number): number {
  const n = Math.max(0, Math.floor(tiles));
  const s = Math.max(1, Math.floor(steps));
  const k = Math.min(s, Math.max(0, Math.floor(step)));
  return Math.round((k / s) * n);
}

/** Points for a right guess made at `step` of `steps`. */
export function guessPoints(step: number, steps: number, options: { max?: number; floor?: number } = {}): number {
  const { max = 1000, floor = 0.2 } = options;
  const s = Math.max(1, Math.floor(steps));
  const k = Math.min(s, Math.max(0, step));
  const share = 1 - (1 - Math.min(1, Math.max(0, floor))) * (k / s);
  return Math.round(max * share);
}
